const enhancedMap = new Map<string, EnhancedAgentDefinition>();

function initEnhanced() {
  if (enhancedMap.size > 0) return;
  for (const def of ENHANCED_AGENTS) {
    enhancedMap.set(def.id, def);
  }
}

export function getEnhancedAgent(id: string): EnhancedAgentDefinition | undefined {
  initEnhanced();
  return enhancedMap.get(id);
}

export function getAllEnhancedAgents(): EnhancedAgentDefinition[] {
  initEnhanced();
  return Array.from(enhancedMap.values());
}

export function getFullAgentProfile(id: string) {
  initAgents();
  initEnhanced();
  const base = agents.get(id);
  const enhanced = enhancedMap.get(id);
  if (!base) return undefined;
  return { ...base, ...(enhanced ?? {}) };
}

export function getAllFullAgentProfiles() {
  initAgents();
  initEnhanced();
  return Array.from(agents.values()).map(base => {
    const enhanced = enhancedMap.get(base.id);
    return { ...base, ...(enhanced ?? {}) };
  });
}
